import boto3
from botocore.exceptions import ClientError

DYNAMO_CLIENT = boto3.client('dynamodb')

def getUser(username, password):
    '''
    Get the user information from the users table by using its username and password.
    '''
    try:
        response = DYNAMO_CLIENT.get_item(
            TableName='users',
            Key={
                'username': {'S': username}
            }
        )

        user = response.get('Item')
        if user and user.get('password', {}).get('S') == password:
            return {
                'username': user['username']['S'],
                'other_info': user.get('other_info', {}).get('S', '')
            }
        else:
            return None
    except ClientError as e:
        print(f"Error retrieving user: {e.response['Error']['Message']}")
        return None
